// Generador de Medallón Sacro Vectorial SVG como fallback elegante sin conexión
window.makeSacredFallbackSvg = function(title, subtitle) {
  const safeTitle = (title || "Santa María").replace(/[<>&"']/g, "");
  const safeSub = (subtitle || "Ora pro nobis").replace(/[<>&"']/g, "");
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 800">
    <defs>
      <radialGradient id="gBg" cx="50%" cy="38%" r="65%">
        <stop offset="0%" stop-color="#332414"/>
        <stop offset="100%" stop-color="#120C07"/>
      </radialGradient>
      <linearGradient id="gGold" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stop-color="#FFF5CC"/>
        <stop offset="50%" stop-color="#D8B256"/>
        <stop offset="100%" stop-color="#8A6414"/>
      </linearGradient>
    </defs>
    <rect width="600" height="800" fill="url(#gBg)"/>
    <rect x="28" y="28" width="544" height="744" rx="18" fill="none" stroke="url(#gGold)" stroke-width="3"/>
    <circle cx="300" cy="310" r="155" fill="none" stroke="url(#gGold)" stroke-width="2.5" stroke-dasharray="6,6"/>
    <circle cx="300" cy="310" r="135" fill="none" stroke="url(#gGold)" stroke-width="4"/>
    <g fill="url(#gGold)">
      <rect x="290" y="195" width="20" height="105" rx="3"/>
      <rect x="245" y="220" width="110" height="20" rx="3"/>
      <rect x="220" y="286" width="160" height="16" rx="3"/>
      <path d="M225 390 L248 278 L272 278 L300 342 L328 278 L352 278 L375 390 L350 390 L335 310 L307 372 L293 372 L265 310 L250 390 Z"/>
    </g>
    <text x="300" y="545" text-anchor="middle" fill="#F5E4B8" font-family="Georgia, serif" font-size="24" font-weight="bold">${safeTitle.slice(0, 38)}</text>
    <text x="300" y="585" text-anchor="middle" fill="#D8B256" font-family="Georgia, serif" font-style="italic" font-size="18">${safeSub.slice(0, 48)}</text>
    <text x="300" y="640" text-anchor="middle" fill="#C49E50" font-family="Georgia, serif" font-size="15">✠ Sub tuum praesidium confugimus ✠</text>
  </svg>`;
  return "data:image/svg+xml;utf8," + encodeURIComponent(svg);
};

