window.MARIAN_ADVOCATIONS = [
  { num: 1, yearNumeric: 40, yearDisplay: "Año 40 d.C.", name: "Nuestra Señora del Pilar de Zaragoza", place: "Zaragoza, España · 2 de enero del año 40 d.C.", keywords: "pilar zaragoza espana hispanidad santiago apostol calanda 40", approval: "Culto apostólico inmemorial; Oficio propio confirmado por Inocencio XIII (1723) y Clemente XII · Fiesta: 12 de octubre", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Encaustic_Virgin.jpg/500px-Encaustic_Virgin.jpg", history: `<p>Primera manifestación mariana de la historia cristiana: viviendo aún en carne mortal en Jerusalén, la Santísima Virgen vino a Caesaraugusta (Zaragoza) sobre una columna de jaspe transportada por los ángeles para confortar al Apóstol Santiago el Mayor y a los primeros discípulos de Hispania.</p>`, miracles: "Promesa de que la fe permanecerá firme en España junto al Santo Pilar hasta el fin de los tiempos, y el célebre «Milagro de Calanda» (29 de marzo de 1640), donde fue restituida instantáneamente a Miguel Juan Pellicer la pierna derecha que le había sido amputada dos años y cinco meses antes.", prayer: "«¡Oh Virgen Santísima del Pilar, columna firme de nuestra fe!: conserva en nuestras familias la pureza de la doctrina apostólica y la fortaleza en las tribulaciones. Amén.»" },
  { num: 2, yearNumeric: 352, yearDisplay: "Año 352 / 431", name: "Nuestra Señora de las Nieves (Salus Populi Romani)", place: "Monte Esquilino, Roma · 5 de agosto de 352 y Concilio de Éfeso (431)", keywords: "nieves salus populi romani roma santa maria la mayor liberio sixto iii", approval: "Basílica Papal de Santa María la Mayor erigida por el Papa Liberio (352) y reconstruida por San Sixto III (432) · Fiesta: 5 de agosto", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Encaustic_Virgin.jpg/500px-Encaustic_Virgin.jpg", history: `<p>En la noche del 4 al 5 de agosto del año 352 —en pleno estío romano—, una nevada milagrosa trazó sobre la colina del Esquilino la planta de la Basílica de Santa María la Mayor, primer santuario mariano de Occidente donde se venera el icono atribuido a San Lucas llamado <em>Salus Populi Romani</em>.</p>`, miracles: "Cesación de la gran peste de Roma en 590 bajo San Gregorio Magno, victoria de Lepanto bajo San Pío V y amparo especial de Roma bajo S.S. Pío XII.", prayer: "«Santa María de las Nieves, Salus Populi Romani, conserva la pureza de nuestra fe y alcánzanos la eterna alegría. Amén.»" },
  { num: 3, yearNumeric: 380, yearDisplay: "Siglo IV (Misterio Evangélico)", name: "Nuestra Señora de la Anunciación (Encarnación)", place: "Nazaret, Galilea (Lc 1, 26–38) · Fiesta antiquísima del siglo IV", keywords: "anunciacion encarnacion nazaret gabriel fiat montfort 25 marzo", approval: "Fiesta principal de la Consagración Total prescrita por San Luis María de Montfort (TVD, n. 243) · Solemnidad: 25 de marzo", img: "assets/img/consagracion.webp", history: `<p>Conmemora el instante en que, al «Fiat» humilde y libre de la Virgen María ante el Arcángel San Gabriel, el Verbo Eterno se encarnó en sus entrañas purísimas y quiso depender voluntariamente de su Madre.</p>`, miracles: "El milagro supremo de todos los siglos: la Unión Hipostática del Hijo de Dios en el claustro virginal de María, principio de nuestra redención.", prayer: "«He aquí la esclava del Señor; hágase en mí según tu palabra. Y el Verbo se hizo carne y habitó entre nosotros. Amén.»" },
  { num: 4, yearNumeric: 722, yearDisplay: "Año 722", name: "Nuestra Señora de Covadonga (La Santina)", place: "Santa Cueva del Monte Auseva, Asturias, España · Mayo del año 722", keywords: "covadonga santina asturias don pelayo reconquista 722", approval: "Venerada desde el inicio de la Reconquista y coronada canónicamente en su XII centenario el 8 de septiembre de 1918 bajo Benedicto XV · Fiesta: 8 de septiembre", img: "assets/img/advocaciones.webp", history: `<p>En el año 722, cuando el caudillo visigodo Don Pelayo y trescientos guerreros cristianos resistían en la cueva del monte Auseva frente al ejército invasor de Alkama, se encomendaron a la imagen de la Virgen venerada en la gruta, dando inicio a la Reconquista cristiana.</p>`, miracles: "Según las crónicas de Alfonso III, las flechas y piedras disparadas contra la cueva de la Virgen retrocedían en el aire por virtud divina contra los propios atacantes.", prayer: "«Virgen de Covadonga, sé nuestra capitana y refugio en el combate por el Reino de Cristo. Amén.»" },
  { num: 5, yearNumeric: 880, yearDisplay: "Año 880", name: "Nuestra Señora de Montserrat (La Moreneta)", place: "Montaña de Montserrat, Cataluña, España · Año 880", keywords: "montserrat moreneta cataluna barcelona san ignacio loyola 880", approval: "Proclamada y coronada canónicamente por S.S. León XIII el 11 de septiembre de 1881 · Fiesta: 27 de abril", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Vladimirskaya.jpg/500px-Vladimirskaya.jpg", history: `<p>Hallada en el año 880 en una cueva de la montaña de Montserrat gracias a luces y melodías angélicas; ante su altar realizó San Ignacio de Loyola su histórica vela de armas en la noche del 24 al 25 de marzo de 1522.</p>`, miracles: "Inmovilidad prodigiosa de la talla cuando se intentó sacarla de la montaña y conversión heroica de grandes santos a sus plantas.", prayer: "«Reina y Madre de Montserrat, recibe a tus pies nuestras armas mundanas y vistenos de la humildad de Cristo. Amén.»" },
  { num: 6, yearNumeric: 1061, yearDisplay: "Año 1061", name: "Nuestra Señora de Walsingham (Dote de María)", place: "Walsingham, Norfolk, Inglaterra · Año 1061", keywords: "walsingham inglaterra santa casa richeldis 1061", approval: "Aprobada por los Papas medievales y restaurada solemnemente por S.S. León XIII el 6 de febrero de 1897 · Fiesta: 24 de septiembre", img: "assets/img/consagracion.webp", history: `<p>En 1061, la Santísima Virgen se apareció tres veces a la noble anglosajona Richeldis de Faverches, mostrándole en espíritu las medidas de la Santa Casa de la Anunciación de Nazaret para edificar su réplica en Inglaterra.</p>`, miracles: "Ensamblaje angélico de la capilla durante la noche junto a dos manantiales curativos que hicieron de Inglaterra la «Dote de María».", prayer: "«Nuestra Señora de Walsingham, por el gozo de la Anunciación devuelve los corazones errantes a la unidad de la Iglesia Católica. Amén.»" },
  { num: 7, yearNumeric: 1208, yearDisplay: "Año 1208 / 1571", name: "Nuestra Señora del Santísimo Rosario", place: "Prouille, Francia (1208) y Golfo de Lepanto (7 de octubre de 1571)", keywords: "rosario victorias lepanto santo domingo guzman san pio v 1208 1571", approval: "Fiesta instituida por el Papa San Pío V (1571), Gregorio XIII (1573) y doce encíclicas de León XIII · Fiesta: 7 de octubre", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/2017-03_Brescia_Mattes_Pana_%28111%29.JPG/500px-2017-03_Brescia_Mattes_Pana_%28111%29.JPG", history: `<p>Entrega del Salterio mariano a Santo Domingo de Guzmán en 1208 contra la herejía albigense y victoria naval de la Liga Santa en Lepanto el 7 de octubre de 1571 por el rezo público del Rosario.</p>`, miracles: "Las Quince Promesas reveladas al Beato Alano de la Rupe y las victorias históricas de Lepanto (1571), La Naval de Manila (1646) y Viena (1683).", prayer: "«Reina del Santísimo Rosario, enséñanos a meditar con tu corazón los misterios de la Vida, Pasión y Gloria de tu Hijo. Amén.»" },
  { num: 8, yearNumeric: 1218, yearDisplay: "Año 1218", name: "Nuestra Señora de la Merced (Redención de Cautivos)", place: "Barcelona, España · Noche del 1 al 2 de agosto de 1218", keywords: "merced mercedes barcelona san pedro nolasco cautivos 1218", approval: "Orden aprobada por Gregorio IX (1235) y fiesta universal por Inocencio XII en 1696 · Fiesta: 24 de septiembre", img: "assets/img/advocaciones.webp", history: `<p>Aparición en Barcelona a San Pedro Nolasco, San Raimundo de Peñafort y el rey Jaime I de Aragón pidiendo fundar una orden consagrada a redimir a los cristianos cautivos en peligro de apostatar.</p>`, miracles: "Más de 80.000 cautivos cristianos rescatados de las mazmorras a lo largo de cinco siglos bajo el manto de Nuestra Señora de la Merced.", prayer: "«Madre de la Merced, rompe las cadenas de nuestras culpas y guárdanos en la santa esclavitud de tu amor. Amén.»" },
  { num: 9, yearNumeric: 1239, yearDisplay: "Año 1239", name: "Nuestra Señora de los Dolores (Mater Dolorosa)", place: "Calvario / Monte Senario, Florencia, Italia · Año 1239", keywords: "dolores dolorosa siete dolores servitas calvario stabat mater 1239", approval: "Extendida a la Iglesia universal por Pío VII (1814) y fijada el 15 de septiembre por San Pío X · Fiesta: 15 de septiembre", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Salamanca_-_Iglesia_de_la_Vera_Cruz_12.jpg/500px-Salamanca_-_Iglesia_de_la_Vera_Cruz_12.jpg", history: `<p>Contemplación de los Siete Dolores de la Madre Corredentora unida a la Pasión de Cristo (Jn 19, 25), confiada en 1239 a los Siete Santos Fundadores de la Orden de los Siervos de María.</p>`, miracles: "Promesas de contrición perfecta antes de la muerte y el milagro de los ojos de la Dolorosa del Colegio San Gabriel en Quito (20 de abril de 1906).", prayer: "«Haz, oh Madre, fuente de amor, que sienta la fuerza de tu dolor para que llore contigo al pie de la Cruz. Amén.»" },
  { num: 10, yearNumeric: 1251, yearDisplay: "16 de julio de 1251", name: "Nuestra Señora del Monte Carmelo (Virgen del Carmen)", place: "Monte Carmelo / Cambridge, Inglaterra · 16 de julio de 1251", keywords: "carmen monte carmelo escapulario san simon stock privilegio sabatino 1251", approval: "Aprobada por Inocencio IV (1247), Paulo V (1613), Benedicto XIII (1726) y San Pío X (1910) · Fiesta: 16 de julio", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Holy_Land_2016_P0262_Stella_Maris_Monastery_maina_altar_Our_Lady_of_mount_Carmel.jpg/500px-Holy_Land_2016_P0262_Stella_Maris_Monastery_maina_altar_Our_Lady_of_mount_Carmel.jpg", history: `<p>El 16 de julio de 1251, la Santísima Virgen se apareció a San Simón Stock, Prior General Carmelita, entregándole el Santo Escapulario marrón como vestidura de alianza y consagración.</p>`, miracles: "La Gran Promesa («El que muriere revestido con este santo hábito no padecerá el fuego eterno») y el Privilegio Sabatino confirmado bajo Paulo V para la pronta liberación del Purgatorio.", prayer: "«Flor del Carmelo, Viña florida, Esplendor del cielo, Virgen fecunda y singular: ¡oh Madre tierna, intacta de hombre, a tus hijos protege siempre, Estrella del mar! Amén.»" },
  { num: 11, yearNumeric: 1270, yearDisplay: "Siglo XIII (1270)", name: "Nuestra Señora del Rocío (Blanca Paloma)", place: "Las Rocinas, Almonte, Huelva, España · Siglo XIII (1270)", keywords: "rocio blanca paloma almonte huelva pentecostes 1270", approval: "Ermita histórica de Alfonso X el Sabio (1270); coronada canónicamente por decreto de S.S. Benedicto XV el 8 de junio de 1919 · Fiesta: Lunes de Pentecostés", img: "assets/img/dogmas.webp", history: `<p>Antigua talla gótica hallada intacta en el hueco de un acebuche de Las Rocinas (Doñana), donde el rey Alfonso X el Sabio mandó edificar su primera ermita en 1270.</p>`, miracles: "Protección portentosa de la comarca durante el gran terremoto de Lisboa del 1 de noviembre de 1755.", prayer: "«Blanca Paloma del Rocío, Esposa del Espíritu Santo, abrasa nuestros corazones en el fuego del divino Amor. Amén.»" },
  { num: 12, yearNumeric: 1294, yearDisplay: "10 de diciembre de 1294", name: "Nuestra Señora de Loreto (La Santa Casa)", place: "Nazaret a Tersatto (1291) y Loreto, Italia (10 de diciembre de 1294)", keywords: "loreto santa casa nazaret letanias lauretanas aviacion 1294", approval: "Bula de Sixto V (1587) aprobando las Letanías Lauretanas y Decreto de Benedicto XV (1920) · Fiesta: 10 de diciembre", img: "assets/img/consagracion.webp", history: `<p>Traslación prodigiosa de los muros de piedra de la Santa Casa de Nazaret —donde el Verbo se hizo carne— para preservarlos de la invasión mameluca de Tierra Santa en 1291–1294.</p>`, miracles: "Asentamiento de los muros sin cimientos propios sobre el suelo de Loreto y correspondencia arqueológica exacta con la gruta de Nazaret.", prayer: "«Virgen Lauretana, Casa de Oro donde habitó la Sabiduría Encarnada: haz de nuestras almas morada pura de tu Hijo. Amén.»" },
  { num: 13, yearNumeric: 1326, yearDisplay: "Siglo XIV (c. 1326 / 1340)", name: "Santa María de Guadalupe de Extremadura", place: "Río Guadalupe, Cáceres, España · c. 1326 / Batalla del Salado (1340)", keywords: "guadalupe extremadura caceres espana gil cordero alfonso xi colon 1340", approval: "Santuario real de Alfonso XI (1340); coronada como Reina de las Españas con bula de S.S. Pío XI el 12 de octubre de 1928 · Fiesta: 6 de septiembre", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Vladimirskaya.jpg/500px-Vladimirskaya.jpg", history: `<p>Antiquísima talla románica hallada junto al río Guadalupe por el pastor cacereño Gil Cordero tras aparecérsele Nuestra Señora.</p>`, miracles: "Resurrección del hijo difunto de Gil Cordero, victoria del Salado (1340) y bautismo de los primeros indígenas de América apadrinados por los Reyes Católicos.", prayer: "«Santa María de Guadalupe de Extremadura, conserva en toda la Hispanidad la fe católica de nuestros mayores. Amén.»" },
  { num: 14, yearNumeric: 1382, yearDisplay: "Agosto de 1382", name: "Nuestra Señora de Częstochowa (Reina de Polonia)", place: "Jasna Góra (Monte Claro), Polonia · Agosto de 1382", keywords: "czestochowa jasna gora polonia virgen negra 1382", approval: "Coronada por Clemente XI (1717), San Pío X (1910) y Pío XI (1925) · Fiesta: 26 de agosto", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Vladimirskaya.jpg/500px-Vladimirskaya.jpg", history: `<p>Venerable icono custodiado desde 1382 en el monasterio de Jasna Góra, que conserva las cicatrices de los sables husitas de 1430 y ante el cual Polonia fue consagrada en 1656.</p>`, miracles: "Defensa victoriosa del monasterio en 1655 y el «Milagro del Vístula» del 15 de agosto de 1920 frente a la invasión bolchevique.", prayer: "«Reina de Jasna Góra, defiende la fe católica de las familias y de las naciones. Amén.»" },
  { num: 15, yearNumeric: 1392, yearDisplay: "Año 1392", name: "Nuestra Señora de la Candelaria", place: "Templo de Jerusalén y Tenerife, España (1392)", keywords: "candelaria purificacion tenerife canarias 2 febrero 1392", approval: "Fiesta litúrgica de la Purificación (2 de febrero) y patronazgo confirmado por Clemente VIII (1599) y Pío IX (1867) · Fiesta: 2 de febrero", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Candelaria_entre_guanches.jpg/500px-Candelaria_entre_guanches.jpg", history: `<p>Une el misterio litúrgico de la Purificación de María y Presentación del Niño Jesús como Luz de las naciones con su aparición en Tenerife en 1392 a los pastores guanches.</p>`, miracles: "Curación instantánea de los pastores guanches y candelas encendidas por manos angélicas en la cueva de Achbinico.", prayer: "«Virgen de la Candelaria, presenta nuestras almas purificadas ante el Trono de tu Hijo, Luz del mundo. Amén.»" },
  { num: 16, yearNumeric: 1414, yearDisplay: "Año 1414", name: "Nuestra Señora de los Inocentes y Desamparados", place: "Valencia, España · Años 1409 – 1414", keywords: "desamparados valencia padre jofre geperudeta 1414", approval: "Aprobada por Benedicto XIII, León XIII (1885) y coronada con breve de S.S. Pío XI el 12 de mayo de 1923 · Fiesta: 2.º domingo de mayo", img: "assets/img/consagracion.webp", history: `<p>Nacida en Valencia con el primer hospital psiquiátrico fundado por el mercedario Fray Juan Gilabert Jofré en 1409 para amparar a los inocentes, huérfanos y desvalidos.</p>`, miracles: "El «Milagro de los Peregrinos» de 1414, en que tres ángeles en figura de peregrinos esculpieron en tres días dentro de un cuarto cerrado su bellísima imagen inclinada hacia los que sufren.", prayer: "«Madre de los Desamparados, inclina hacia nosotros tu mirada compasiva y no nos dejes solos en la tribulación. Amén.»" },
  { num: 17, yearNumeric: 1467, yearDisplay: "25 de abril de 1467", name: "Nuestra Señora del Buen Consejo de Genazzano", place: "Escútari (Albania) a Genazzano, Italia · 25 de abril de 1467", keywords: "buen consejo genazzano albania leon xiii 1467", approval: "Investigada por el Papa Paulo II (1467) e incluida en las Letanías Lauretanas por S.S. León XIII en 1903 · Fiesta: 26 de abril", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Vladimirskaya.jpg/500px-Vladimirskaya.jpg", history: `<p>Traslación milagrosa del fresco de Nuestra Señora desde Albania invadida por los otomanos hasta el santuario agustino de Genazzano el 25 de abril de 1467.</p>`, miracles: "Suspensión física inexplicable del delgadísimo fresco en el aire sin apoyo trasero desde 1467 y preservación intacta durante el bombardeo de la basílica en 1944.", prayer: "«Madre del Buen Consejo, ilumina nuestras decisiones con el don de consejo del Espíritu Santo. Amén.»" },
  { num: 18, yearNumeric: 1499, yearDisplay: "Año 1499 / 1866", name: "Nuestra Señora del Perpetuo Socorro", place: "Creta / Roma (San Mateo en 1499 y San Alfonso en 1866)", keywords: "perpetuo socorro roma redentoristas pio ix 1499 1866", approval: "Venerada en Roma desde 1499; entregada por el Papa Pío IX a los Redentoristas en 1866 y coronada en 1867 · Fiesta: 27 de junio", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Our_Holy_Mother_Of_Perpetual_Succour.jpg/500px-Our_Holy_Mother_Of_Perpetual_Succour.jpg", history: `<p>Antiquísimo icono oriental de la Virgen de la Pasión donde los arcángeles San Miguel y San Gabriel muestran al Niño Jesús los instrumentos de la Crucifixión.</p>`, miracles: "Aparición de la Virgen en Roma en 1499 ordenando exponer su icono bajo el título del Perpetuo Socorro y mandato de Pío IX en 1866: «Dadla a conocer a todo el mundo».", prayer: "«¡Oh Madre del Perpetuo Socorro, cuyo solo nombre inspira confianza!: socórreme en toda tentación y en la hora de mi muerte. Amén.»" },
  { num: 19, yearNumeric: 1531, yearDisplay: "9 al 12 de diciembre de 1531", name: "Nuestra Señora de Guadalupe, Emperatriz de América", place: "Cerro del Tepeyac, México · 9 al 12 de diciembre de 1531", keywords: "guadalupe mexico tepeyac juan diego tilma zumarraga 1531", approval: "Aprobada en 1531; Benedicto XIV (1754), León XIII (1895), San Pío X (1910) y Pío XII (1945) · Fiesta: 12 de diciembre", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/1531_Nuestra_Se%C3%B1ora_de_Guadalupe_anagoria.jpg/500px-1531_Nuestra_Se%C3%B1ora_de_Guadalupe_anagoria.jpg", history: `<p>Aparición de la Siempre Virgen Santa María, Madre del verdadero Dios, al indio Juan Diego Cuauhtlatoatzin en el Tepeyac, dejando estampada milagrosamente su Sagrada Imagen en la tilma ante el obispo Fray Juan de Zumárraga el 12 de diciembre de 1531.</p>`, miracles: "Conversión de millones de indígenas, conservación incorrupta de la tilma de maguey por más de cuatro siglos y supervivencia intacta al ácido nítrico (1785) y al atentado con dinamita (1921).", prayer: "«¿No estoy Yo aquí que soy tu Madre? ¿No estás bajo mi sombra y resguardo? — ¡Santa María de Guadalupe, Emperatriz de América, guarda nuestra fe! Amén.»" },
  { num: 20, yearNumeric: 1583, yearDisplay: "2 de febrero de 1583", name: "Nuestra Señora de Copacabana", place: "Lago Titicaca, Bolivia · 2 de febrero de 1583", keywords: "copacabana bolivia titicaca tito yupanqui 1583", approval: "Coronada canónicamente y proclamada Reina de Bolivia con breve de S.S. Pío XI el 1 de agosto de 1925 · Fiesta: 5 de agosto", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Candelaria_entre_guanches.jpg/500px-Candelaria_entre_guanches.jpg", history: `<p>Esculpida con ayunos, oraciones y misas a la Santísima Trinidad por el escultor indígena inca Francisco Tito Yupanqui y entronizada en Copacabana el 2 de febrero de 1583.</p>`, miracles: "Transformación sobrenatural de la belleza del rostro y cambio milagroso de la postura del Niño Jesús para no estorbar la corona de su Madre.", prayer: "«Virgen Santísima de Copacabana, bendice nuestras fatigas y une a las familias en la caridad de Cristo. Amén.»" },
  { num: 21, yearNumeric: 1586, yearDisplay: "26 de diciembre de 1586", name: "Nuestra Señora del Rosario de Chiquinquirá", place: "Chiquinquirá, Boyacá, Colombia · 26 de diciembre de 1586", keywords: "chiquinquira colombia maria ramos boyaca 1586", approval: "Juicio canónico de 1587; Patrona de Colombia por Pío VII (1829) y coronada por decreto de San Pío X (1919) · Fiesta: 9 de julio", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e8/2017-03_Brescia_Mattes_Pana_%28111%29.JPG/500px-2017-03_Brescia_Mattes_Pana_%28111%29.JPG", history: `<p>Ante las súplicas perseverantes de María Ramos, el viernes 26 de diciembre de 1586 un lienzo rasgado y borrado de la Virgen del Rosario descendió rodeado de luz y renovó milagrosamente sus colores y tejido.</p>`, miracles: "Renovación física del tejido de algodón roto y de sus pigmentos verificada en el proceso canónico de 1587, y cese de la peste de Tunja en 1588.", prayer: "«Reina del Rosario de Chiquinquirá, renueva en nuestras almas la gracia santificante y el esplendor de las virtudes. Amén.»" },
  { num: 22, yearNumeric: 1594, yearDisplay: "2 de febrero de 1594 / 1611", name: "Nuestra Señora del Buen Suceso de Quito", place: "Real Monasterio de la Limpia Concepción, Quito, Ecuador · 1594 – 1634", keywords: "buen suceso quito ecuador madre mariana de jesus torres 1594 1611", approval: "Estatua milagrosa concluida por los Arcángeles y San Francisco de Asís y bendecida por el IX Obispo de Quito, Mons. Salvador de Ribera, el 2 de febrero de 1611 · Fiesta: 2 de febrero", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/OUR_LADY_OF_GOOD_SUCCESS_IN_QUITO.jpg/500px-OUR_LADY_OF_GOOD_SUCCESS_IN_QUITO.jpg", history: `<p>En el Real Monasterio de la Limpia Concepción de Quito, la Santísima Virgen se apareció desde el 2 de febrero de 1594 a la abadesa española Madre Mariana Francisca de Jesús Torres (1563–1635), pidiéndole ofrecerse como víctima expiatoria por los cristianos del siglo XX y mandando tallar su sagrada estatua con el báculo abacial y las llaves del claustro.</p>`, miracles: "La lámpara del Santísimo que se apagó misteriosamente anunciando las graves crisis morales y doctrinales del siglo XX, seguida de su promesa infalible: «Cuando todo parezca perdido y paralizado, será el feliz principio de la completa restauración: esa hora será la mía, en que destronaré al soberbio Satanás».", prayer: "«¡Oh María Santísima del Buen Suceso, Reina de las Victorias y Madre de la fe íntegra!: sostén nuestras almas en medio de las tinieblas presentes y apresura la hora bendita de tu triunfo maternal. Amén.»" },
  { num: 23, yearNumeric: 1612, yearDisplay: "Año 1612", name: "Nuestra Señora de la Caridad del Cobre", place: "Bahía de Nipe, Oriente de Cuba · Año 1612", keywords: "caridad del cobre cuba tres juanes nipe 1612", approval: "Declarada Patrona de Cuba por S.S. Benedicto XV el 10 de mayo de 1916 y coronada bajo Pío XI en 1936 · Fiesta: 8 de septiembre", img: "assets/img/consagracion.webp", history: `<p>Hallada a inicios de 1612 por «los tres Juanes» flotando sobre una tabla en las aguas de la bahía de Nipe tras una tormenta, con la inscripción: «Yo soy la Virgen de la Caridad».</p>`, miracles: "A pesar de flotar sobre las olas tras la tempestad, las vestiduras de tela de la imagen estaban completamente secas (atestiguado bajo juramento canónico en 1687).", prayer: "«Virgen de la Caridad del Cobre, guíanos en las tempestades de esta vida hasta el puerto de la eternidad. Amén.»" },
  { num: 24, yearNumeric: 1630, yearDisplay: "Mayo de 1630", name: "Nuestra Señora de Luján", place: "Río Luján, Provincia de Buenos Aires, Argentina · Mayo de 1630", keywords: "lujan argentina negro manuel pura y limpia concepcion 1630", approval: "Coronada canónicamente por S.S. León XIII el 8 de mayo de 1887 y Patrona por Pío XI en 1930 · Fiesta: 8 de mayo", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Bartolom%C3%A9_Esteban_Perez_Murillo_021.jpg/500px-Bartolom%C3%A9_Esteban_Perez_Murillo_021.jpg", history: `<p>En mayo de 1630, la carreta que llevaba su pequeña imagen de terracota de la Pura y Limpia Concepción quedó prodigiosamente inmovilizada a orillas del río Luján hasta que bajaron la caja de la Virgen para edificarle allí su capilla bajo la custodia del fiel esclavo Negro Manuel.</p>`, miracles: "Detención inexplicable de la carreta y traslados nocturnos milagrosos de la imagen al sitio elegido por Ella.", prayer: "«Pura y Limpia Concepción de Luján, quédate siempre en nuestros hogares y guárdanos sin mancha. Amén.»" },
  { num: 25, yearNumeric: 1652, yearDisplay: "8 de septiembre de 1652", name: "Nuestra Señora de Coromoto", place: "Río Tucupido, Guanare, Venezuela · 8 de septiembre de 1652", keywords: "coromoto venezuela guanare cacique cospes 1652", approval: "Aprobada en 1696; Patrona de Venezuela por S.S. Pío XII (1944) y coronada en 1952 · Fiesta: 11 de septiembre", img: "assets/img/consagracion.webp", history: `<p>Aparición en la quebrada y en el bohío del cacique Coromoto mandándole recibir el Santo Bautismo y dejando en su mano una diminuta reliquia en pergamino de 27 por 22 milímetros con su efigie celestial.</p>`, miracles: "Conservación de la reliquia microscópica y conversión fervorosa del cacique Coromoto tras ser mordido por una serpiente venenosa.", prayer: "«Virgen Santísima de Coromoto, conserva e ilumina en nuestras almas la gracia de las aguas del Santo Bautismo. Amén.»" },
  { num: 26, yearNumeric: 1703, yearDisplay: "24 de junio y 8 de septiembre de 1703", name: "Divina Pastora de las Almas", place: "Sevilla, España · 24 de junio y 8 de septiembre de 1703", keywords: "divina pastora de las almas sor pastora fray isidoro sevilla diego jose de cadiz capuchinos 1703", approval: "Oficio y Misa propios aprobados por S.S. el Papa Pío VI el 1 de agosto de 1795; propagada por el Beato Diego José de Cádiz · Fiesta: 8 de septiembre", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/La_Divina_Pastora_de_Marchena.jpg/500px-La_Divina_Pastora_de_Marchena.jpg", history: `<p>Revelada en visión sobrenatural el 24 de junio de 1703 en el convento capuchino de Sevilla a Fray Isidoro de Sevilla, quien la contempló con túnica carmesí, pellico blanco de pastora, manto azul y cayado apacentando al rebaño de los fieles que llevan rosas de Avemarías en sus bocas.</p>`, miracles: "Cuando una oveja extraviada es perseguida por el lobo infernal y clama «Ave María», el Arcángel San Miguel desciende con espada de fuego y la devuelve salva al redil de la Divina Pastora. Obró conversiones masivas en las misiones capuchinas de España y América.", prayer: "«¡Oh Amabilísima y Divina Pastora de las almas!: recógenos bajo tu cayado maternal, líbranos del lobo infernal y llévanos a los pastos eternos de tu Hijo, el Buen Pastor. Amén.»" },
  { num: 27, yearNumeric: 1717, yearDisplay: "Octubre de 1717", name: "Nuestra Señora de la Concepción Aparecida", place: "Río Paraíba del Sur, Brasil · Octubre de 1717", keywords: "aparecida brasil rio paraiba pescadores 1717", approval: "Coronada por mandato de San Pío X (1904) y proclamada Reina y Patrona del Brasil por S.S. Pío XI el 16 de julio de 1930 · Fiesta: 12 de octubre", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Bartolom%C3%A9_Esteban_Perez_Murillo_021.jpg/500px-Bartolom%C3%A9_Esteban_Perez_Murillo_021.jpg", history: `<p>Hallada en octubre de 1717 por tres humildes pescadores en el río Paraíba, quienes sacaron en sus redes primero el cuerpo y enseguida la cabeza que completaba la pequeña imagen de terracota de la Inmaculada.</p>`, miracles: "Pesca sobreabundante inmediata tras horas de redes vacías, cirios que se encendieron solos y caída de las cadenas del esclavo Zacarías.", prayer: "«Señora nuestra Aparecida, rescátanos de las aguas profundas del pecado y colma nuestra pobreza con tu gracia. Amén.»" },
  { num: 28, yearNumeric: 1814, yearDisplay: "24 de mayo de 1814 (y Lepanto 1571)", name: "María Auxiliadora de los Cristianos", place: "Lepanto (1571) / Roma (24 de mayo de 1814) / Turín (1868)", keywords: "maria auxiliadora auxilium christianorum san juan bosco pio vii turin 1814", approval: "Fiesta instituida por el Papa Pío VII el 24 de mayo de 1814 y propagada por San Juan Bosco (canonizado por Pío XI en 1934) · Fiesta: 24 de mayo", img: "assets/img/dogmas.webp", history: `<p>Invocación añadida a las Letanías Lauretanas por San Pío V tras Lepanto y consagrada con fiesta propia por Pío VII al entrar libre en Roma el 24 de mayo de 1814 tras el cautiverio napoleónico.</p>`, miracles: "El sueño profético de las Dos Columnas de San Juan Bosco (1862), donde la barca de la Iglesia vence la tempestad amarrándose a la Eucaristía y a María Auxiliadora.", prayer: "«María Auxiliadora de los Cristianos, ruega por nosotros y defiende a la Santa Iglesia de toda asechanza. Amén.»" },
  { num: 29, yearNumeric: 1830, yearDisplay: "18 de julio y 27 de noviembre de 1830", name: "Nuestra Señora de la Medalla Milagrosa", place: "Rue du Bac, París, Francia · 27 de noviembre de 1830", keywords: "medalla milagrosa paris rue du bac santa catalina laboure ratisbona 1830", approval: "Juicio canónico de París (1836); Fiesta propia por León XIII (1894); Santa Catalina Labouré canonizada por Pío XII (1947) · Fiesta: 27 de noviembre", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Miraculous_medal.jpg/500px-Miraculous_medal.jpg", history: `<p>Aparición a Santa Catalina Labouré mostrando el óvalo con sus manos derramando rayos de gracias y el reverso con la Cruz (la T) sobre la M de María, las doce estrellas y los Dos Sagrados Corazones (icono oficial de esta aplicación).</p>`, miracles: "Curaciones en la epidemia de cólera de París de 1832 y la conversión instantánea del banquero judío Alfonso de Ratisbona en Roma el 20 de enero de 1842.", prayer: "«¡Oh María, sin pecado concebida, rogad por nosotros que recurrimos a Vos! Amén.»" },
  { num: 30, yearNumeric: 1831, yearDisplay: "13 de agosto de 1831", name: "Nuestra Señora del Olvido, Triunfo y Misericordias", place: "Convento del Caballero de Gracia, Madrid, España · 13 de agosto de 1831", keywords: "olvido triunfo misericordias sor patrocinio monja de las llagas madrid gregorio xvi 1831", approval: "Culto público, novena y cofradía aprobados con Bula e indulgencias plenarias por S.S. el Papa Gregorio XVI en 1836 · Fiesta: 13 de agosto y 22 de septiembre", img: "https://upload.wikimedia.org/wikipedia/commons/a/af/Virgen_del_Olvido%2C_Triunfo_y_Misericordias.jpg", history: `<p>El 13 de agosto de 1831, la Santísima Virgen María, acompañada por el Arcángel San Miguel, se apareció en Madrid a la religiosa concepcionista estigmatizada Sor María Rafaela de los Dolores y del Patrocinio (1811–1891, cuyo proceso de beatificación se abrió en 1907 bajo San Pío X), depositando en sus manos su bellísima imagen celeste.</p>`, miracles: "Palabras reveladas a Sor Patrocinio: «Este título es el que más me agrada, porque jamás olvido a los hombres, antes pongo en olvido sus iniquidades para triunfar con mis misericordias». Sostuvo la fe de España durante la persecución decimonónica e impulsó la petición a Pío IX para definir la Inmaculada Concepción.", prayer: "«¡Oh Virgen Soberana del Olvido, Triunfo y Misericordias!: pon en perpetuo olvido nuestras culpas, triunfa sobre las asechanzas del enemigo y derrama sobre nosotros el abismo de tus misericordias. Amén.»" },
  { num: 31, yearNumeric: 1846, yearDisplay: "19 de septiembre de 1846", name: "Nuestra Señora de La Salette (Reconciliadora)", place: "Alpes de Isère, Francia · 19 de septiembre de 1846", keywords: "la salette francia melanie maximin lagrimas 1846", approval: "Aprobada por sentencia pastoral de Mons. Philibert de Bruillard, Obispo de Grenoble, el 19 de septiembre de 1851 bajo Pío IX · Fiesta: 19 de septiembre", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Eglise_de_Corps-statue-82.JPG/500px-Eglise_de_Corps-statue-82.JPG", history: `<p>Aparición entre lágrimas a los pastorcillos Maximin Giraud y Mélanie Calvat exhortando a reparar la blasfemia y la profanación del domingo para detener el brazo de la justicia divina.</p>`, miracles: "Fuente perenne brotada en el lugar seco donde se posó la Virgen y numerosas curaciones certificadas por el obispado de Grenoble.", prayer: "«¡Oh Nuestra Señora de La Salette, Reconciliadora de los pecadores!: concédenos lágrimas de verdadera contrición. Amén.»" },
  { num: 32, yearNumeric: 1858, yearDisplay: "11 de febrero al 16 de julio de 1858", name: "Nuestra Señora de Lourdes (Inmaculada Concepción)", place: "Gruta de Massabielle, Lourdes, Francia · 11 feb. – 16 jul. 1858", keywords: "lourdes francia santa bernadette soubirous massabielle inmaculada 1858", approval: "Aprobada en 1862; Fiesta universal por San Pío X (1907); Santa Bernadette canonizada por Pío XI (1933) · Fiesta: 11 de febrero", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/France-002009_-_Our_Lady_of_Lourdes_%2815774765182%29.jpg/500px-France-002009_-_Our_Lady_of_Lourdes_%2815774765182%29.jpg", history: `<p>Dieciocho apariciones a Santa Bernadette Soubirous en 1858, confirmando el dogma definido cuatro años antes por Pío IX con las palabras: «Yo soy la Inmaculada Concepción».</p>`, miracles: "Brote del manantial milagroso, incorrupción del cuerpo de Santa Bernadette y decenas de curaciones orgánicas instantáneas aprobadas canónicamente.", prayer: "«¡Oh Virgen Inmaculada de Lourdes, Salud de los enfermos y Refugio de los pecadores!: purifica nuestras almas en la penitencia y guárdanos fieles a Jesús. Amén.»" },
  { num: 33, yearNumeric: 1871, yearDisplay: "17 de enero de 1871", name: "Nuestra Señora de Pontmain (Madre de la Esperanza)", place: "Pontmain, Mayenne, Francia · 17 de enero de 1871", keywords: "pontmain esperanza francia crucifijo rojo 1871", approval: "Aprobada canónicamente el 2 de febrero de 1872 por el Obispo de Laval bajo Pío IX · Fiesta: 17 de enero", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Our_Lady_of_Pontmain_Mayenne_France.jpg/500px-Our_Lady_of_Pontmain_Mayenne_France.jpg", history: `<p>Aparición silenciosa en el cielo estrellado a cuatro niños durante la invasión prusiana, mostrando un Crucifijo rojo y el mensaje escrito en oro: «Pero rezad, hijos míos; Dios os escuchará en breve. Mi Hijo se deja conmover».</p>`, miracles: "Detención inmediata del avance militar invasor esa misma noche y retorno salvo de los treinta y ocho soldados de la aldea.", prayer: "«Madre de la Esperanza de Pontmain, puesto que tu Hijo se deja conmover por tus ruegos, alcánzanos su misericordia. Amén.»" },
  { num: 34, yearNumeric: 1879, yearDisplay: "21 de agosto de 1879 / 1933", name: "Nuestra Señora de Knock (1879) y Virgen de Banneux (1933)", place: "Knock, Irlanda (21 de agosto de 1879) y Banneux, Bélgica (1933)", keywords: "knock irlanda banneux beauraing belgica virgen de los pobres 1879 1933", approval: "Comisiones canónicas de Tuam (1879/1936) y aprobación oficial de Banneux el 22 de agosto de 1949 bajo S.S. Pío XII · Fiesta: 21 de agosto / 15 de enero", img: "assets/img/advocaciones.webp", history: `<p>En Knock (1879), quince fieles contemplaron durante dos horas a la Virgen coronada en oración junto a San José, San Juan Evangelista y el Cordero sobre el Altar; en Banneux (1933, aprobada bajo Pío XII en 1949), se manifestó a Mariette Beco como «La Virgen de los Pobres».</p>`, miracles: "En Knock ni una gota de lluvia mojó el suelo de la aparición en medio del temporal; en Banneux brotó el manantial de curaciones aprobado en 1949.", prayer: "«Virgen de los Pobres y Reina de Irlanda, alivia nuestras dolencias del alma y del cuerpo y llévanos al Cordero Divino. Amén.»" },
  { num: 35, yearNumeric: 1917, yearDisplay: "13 de mayo al 13 de octubre de 1917", name: "Nuestra Señora del Rosario de Fátima", place: "Cova da Iria, Fátima, Portugal · 13 de mayo al 13 de octubre de 1917", keywords: "fatima portugal lucia francisco jacinta milagro del sol cova da iria 1917", approval: "Declarada digna de fe el 13 de octubre de 1930 por el Obispo de Leiria; coronada por legado de S.S. Pío XII el 13 de mayo de 1946 · Fiesta: 13 de mayo", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/Virgen_de_F%C3%A1tima.JPG/500px-Virgen_de_F%C3%A1tima.JPG", history: `<p>Seis apariciones en 1917 a los tres pastorcitos Lucía, Francisco y Jacinta pidiendo el rezo diario del Rosario, la enmienda de vida, la penitencia por los pecadores y la devoción reparadora a su Inmaculado Corazón.</p>`, miracles: "El «Milagro del Sol» del 13 de octubre de 1917 ante 70.000 testigos y la promesa solemne: «Por fin, mi Inmaculado Corazón triunfará».", prayer: "«¡Virgen Santísima del Rosario de Fátima!: alcánzanos el espíritu de oración y sacrificio por la conversión de los pecadores. Amén.»" },
  { num: 36, yearNumeric: 1942, yearDisplay: "Consagración de 1942 / Fiesta de 1944", name: "Inmaculado Corazón de María", place: "París (1830) / Pontevedra (1925) / Roma (Consagración de S.S. Pío XII en 1942)", keywords: "inmaculado corazon de maria cinco primeros sabados pontevedra pio xii 1942 1944", approval: "Oficio litúrgico de San Juan Eudes; Consagración del género humano (1942) y Fiesta universal instituida por S.S. Pío XII el 4 de mayo de 1944 · Fiesta: 22 de agosto", img: "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Immaculate_Heart_of_Mary.jpg/500px-Immaculate_Heart_of_Mary.jpg", history: `<p>Honra el Corazón purísimo y maternal de María, a quien S.S. Pío XII consagró el género humano el 31 de octubre y el 8 de diciembre de 1942, y cuya reparación en los Cinco Primeros Sábados fue pedida en Pontevedra el 10 de diciembre de 1925.</p>`, miracles: "La Gran Promesa de asistir en la hora de la muerte con todas las gracias necesarias para la salvación a quienes cumplan devotamente los Cinco Primeros Sábados reparadores.", prayer: "«¡Dulce Corazón de María, sed la salvación del alma mía!»" }
];

// 5. CORPUS DE ORACIONES BILINGÜES
window.PRAYERS = {
  veniCreator: {
    shortName: "Veni Creator",
    title: "Himno «Veni Creator Spiritus» (TVD, n. 227 — Días 1 al 12)",
    es: `Ven, Espíritu Creador, visita las almas de tus fieles y llena de la divina gracia los corazones que Tú mismo creaste.
Tú eres nuestro Consolador, don de Dios Altísimo, fuente viva, fuego, caridad y espiritual unción.
Tú derramas sobre nosotros los siete dones; Tú, el dedo de la mano de Dios; Tú, el prometido del Padre; Tú, que pones en nuestros labios los tesoros de tu palabra.
Enciende con tu luz nuestros sentidos; infunde tu amor en nuestros corazones; y con tu perpetuo auxilio, fortalece nuestra débil carne.
Aleja de nosotros al enemigo, danos pronto la paz, sé nuestro director y nuestro guía, para que evitemos todo mal.
Por Ti conozcamos al Padre, y también al Hijo, y que en Ti, que eres el Espíritu de ambos, creamos en todo tiempo.
Gloria a Dios Padre, y al Hijo que resucitó, y al Espíritu Consolador, por los siglos infinitos. Amén.`,
    la: `Veni, Creator Spiritus, mentes tuorum visita, imple superna gratia, quae tu creasti pectora.
Qui diceris Paraclitus, altissimi donum Dei, fons vivus, ignis, caritas, et spiritalis unctio.
Tu septiformis munere, digitus paternae dexterae, tu rite promissum Patris, sermone ditans guttura.
Accende lumen sensibus, infunde amorem cordibus, infirma nostri corporis virtute firmans perpeti.
Hostem repellas longius, pacemque dones protinus; ductore sic te praevio vitemus omne noxium.
Per te sciamus da Patrem, noscamus atque Filium, teque utriusque Spiritum credamus omni tempore.
Deo Patri sit gloria, et Filio, qui a mortuis surrexit, ac Paraclito, in saeculorum saecula. Amen.`
  },
  aveMarisStella: {
    shortName: "Ave Maris Stella",
    title: "Himno «Ave Maris Stella» (TVD, nn. 227–230 — Todos los 33 días)",
    es: `Salve, Estrella del mar, Madre que diste a luz a Dios, quedando perpetuamente Virgen, feliz puerta del cielo.
Pues recibiste aquel Ave de labios de Gabriel, ciméntanos en la paz, trocando el nombre de Eva.
Suelta las prisiones a los reos, da lumbre a los ciegos, ahuyenta nuestros males y alcánzanos todos los bienes.
Muestra que eres Madre; reciba por tu mediación nuestras plegarias Aquel que, nacido por nosotros, se dignó ser tuyo.
Virgen singular, sobre todas suave, haz que, libres de culpas, seamos mansos y castos.
Danos una vida pura, prepáranos un camino seguro, para que, viendo a Jesús, eternamente nos gocemos.
Gloria sea a Dios Padre, loor a Cristo Altísimo y al Espíritu Santo: a los Tres un solo honor. Amén.`,
    la: `Ave, maris stella, Dei Mater alma, atque semper Virgo, felix caeli porta.
Sumens illud Ave Gabrielis ore, funda nos in pace, mutans Hevae nomen.
Solve vincla reis, profer lumen caecis, mala nostra pelle, bona cuncta posce.
Monstra te esse matrem, sumat per te preces, qui pro nobis natus, tulit esse tuus.
Virgo singularis, inter omnes mitis, nos culpis solutos, mites fac et castos.
Vitam praesta puram, iter para tutum, ut videntes Iesum, semper collaetemur.
Sit laus Deo Patri, summo Christo decus, Spiritui Sancto, tribus honor unus. Amen.`
  },
  magnificat: {
    shortName: "Magnificat",
    title: "Cántico de Nuestra Señora «Magnificat» (Lc 1, 46–55; TVD, n. 255)",
    es: `Glorifica mi alma al Señor, y mi espíritu se llena de gozo al contemplar la bondad de Dios mi Salvador.
Porque ha puesto la mirada en la humilde sierva suya; ved aquí el motivo por que me tendrán por dichosa todas las generaciones.
Pues ha hecho en mí cosas grandes y maravillosas el que es Todopoderoso, y su nombre infinitamente santo.
Cuya misericordia se extiende de generación en generación a todos cuantos le temen.
Extendió el brazo de su poder y disipó el orgullo de los soberbios, trastornando sus designios.
Desposeyó a los poderosos, y elevó a los humildes. A los necesitados los llenó de bienes, y a los ricos los dejó sin cosa alguna.
Exaltó a Israel su siervo, acordándose de él por su gran misericordia y bondad. Así como lo había prometido a nuestros padres, a Abraham y a toda su descendencia por los siglos de los siglos. Amén.`,
    la: `Magnificat anima mea Dominum: et exsultavit spiritus meus in Deo salutari meo.
Quia respexit humilitatem ancillae suae: ecce enim ex hoc beatam me dicent omnes generationes.
Quia fecit mihi magna qui potens est: et sanctum nomen eius. Et misericordia eius a progenie in progenies timentibus eum.
Fecit potentiam in brachio suo: dispersit superbos mente cordis sui. Deposuit potentes de sede, et exaltavit humiles.
Esurientes implevit bonis: et divites dimisit inanes. Suscepit Israel puerum suum, recordatus misericordiae suae.
Sicut locutus est ad patres nostros, Abraham et semini eius in saecula. Amen.`
  },
  letaniasEspiritu: {
    shortName: "Letanías Espíritu Santo",
    title: "Letanías del Espíritu Santo (TVD, nn. 228–230 — Días 13 al 33)",
    es: `Señor, ten piedad. Cristo, ten piedad. Señor, ten piedad.
Padre eterno, Dios, ten piedad de nosotros. Hijo, Redentor del mundo, Dios, ten piedad de nosotros.
Espíritu Santo, Dios, ten piedad de nosotros. Santísima Trinidad, que eres un solo Dios, ten piedad de nosotros.
Espíritu de verdad y de sabiduría, ten piedad de nosotros.
Espíritu de entendimiento y de consejo, ten piedad de nosotros.
Espíritu de fortaleza, de ciencia y de piedad, ten piedad de nosotros.
Espíritu de temor del Señor, de humildad y de pureza, ten piedad de nosotros.
Espíritu Santo, por cuya virtud fue encarnado Jesús en el seno virginal de María, ten piedad de nosotros.
Cordero de Dios, que quitas los pecados del mundo: perdónanos, Señor; escúchanos, Señor; ten piedad de nosotros.`,
    la: `Kyrie, eleison. Christe, eleison. Kyrie, eleison.
Pater de caelis, Deus, miserere nobis. Fili, Redemptor mundi, Deus, miserere nobis.
Spiritus Sancte, Deus, miserere nobis. Sancta Trinitas, unus Deus, miserere nobis.
Spiritus veritatis et sapientiae, intellectus et consilii, fortitudinis, scientiae et pietatis, timoris Domini, miserere nobis.
Spiritus Sancte, qui obumbrasti Virgini Mariae, miserere nobis.
Agnus Dei, qui tollis peccata mundi, parce nobis, Domine / exaudi nos, Domine / miserere nobis.`
  },
  letaniasLauretanas: {
    shortName: "Letanías Lauretanas",
    title: "Letanías de la Santísima Virgen (TVD, nn. 228–229 — Días 13 al 26)",
    es: `Señor, ten piedad. Cristo, ten piedad. Señor, ten piedad. Cristo, óyenos. Cristo, escúchanos.
Santa María, Santa Madre de Dios, Santa Virgen de las vírgenes, Madre de Cristo, Madre de la divina gracia, Madre purísima, Madre castísima, Madre inmaculada, Madre amable, Madre admirable, Madre del buen consejo, Madre del Creador, Madre del Salvador, ruega por nosotros.
Virgen prudentísima, Virgen poderosa, Virgen clemente, Virgen fiel, Espejo de justicia, Trono de la sabiduría, Causa de nuestra alegría, Vaso de verdadera devoción, Rosa mística, Torre de David, Torre de marfil, Casa de oro, Arca de la alianza, Puerta del cielo, Estrella de la mañana, Salud de los enfermos, Refugio de los pecadores, Consoladora de los afligidos, Auxilio de los cristianos, ruega por nosotros.
Reina de los Ángeles, de los Patriarcas, de los Profetas, de los Apóstoles, de los Mártires, de los Confesores, de las Vírgenes y de todos los Santos, Reina concebida sin pecado original, Reina asunta al cielo, Reina del Santísimo Rosario, Reina de la paz, ruega por nosotros.`,
    la: `Kyrie, eleison. Christe, eleison. Kyrie, eleison.
Sancta Maria, Sancta Dei Genitrix, Sancta Virgo virginum, Mater Christi, Mater divinae gratiae, Mater purissima, Mater castissima, Mater inviolata, Mater amabilis, Mater admirabilis, Mater boni consilii, Mater Creatoris, Mater Salvatoris, ora pro nobis.
Virgo prudentissima, Virgo fidelis, Speculum iustitiae, Sedes sapientiae, Causa nostrae laetitiae, Vas insigne devotionis, Rosa mystica, Turris Davidica, Turris eburnea, Domus aurea, Foederis arca, Ianua caeli, Stella matutina, Salus infirmorum, Refugium peccatorum, Auxilium Christianorum, Regina sine labe originali concepta, Regina in caelum assumpta, Regina sacratissimi Rosarii, ora pro nobis.`
  },
  oracionSanAgustin: {
    shortName: "Oración S. Agustín",
    title: "Oración de San Agustín a Jesucristo (TVD, nn. 67 y 230 — Días 27 al 33)",
    es: `Vos sois, ¡oh Jesús!, el Cristo, mi Padre santo, mi Dios misericordioso, mi Rey infinitamente grande; sois mi buen Pastor, mi único Maestro, mi Auxiliador lleno de bondad, mi Amado de una belleza maravillosa, mi Pan vivo, mi Sacerdote eterno, mi Guía hacia la patria, mi verdadera Luz, mi santa Dulzura, mi recto Camino, mi Sabiduría preclara, mi pura Simplicidad, mi Paz y Concordia; sois, en fin, toda mi Salvación, mi Herencia preciosa y mi porción para siempre.
¡Oh Jesucristo, amable Señor! Que a partir de este momento mi corazón no desee sino a Vos; curad mi alma y haced que sea vuestra por medio de María. Amén.`,
    la: `Tu es, o Iesu, Christus, Pater meus sanctus, Deus meus misericors, Rex meus magnus, Pastor meus bonus, Magister meus unus, Adiutor meus optimus, Dilectus meus pulcherrimus, Panis meus vivus, Sacerdos meus in aeternum, Lux mea vera, Dulcedo mea sancta, Via mea recta, Sapientia mea praeclara, Salus mea sempiterna. Amen.`
  },
  letaniasJesus: {
    shortName: "Letanías de Jesús",
    title: "Letanías del Santísimo Nombre de Jesús (TVD, n. 230 — Días 27 al 33)",
    es: `Señor, ten piedad. Cristo, ten piedad. Señor, ten piedad. Jesús, óyenos. Jesús, escúchanos.
Jesús, Hijo de Dios vivo, resplandor del Padre, pureza de la luz eterna, Rey de la gloria, Sol de justicia, Hijo de la Virgen María, ten piedad de nosotros.
Jesús amable, admirable, Dios fuerte, poderosísimo, pacientísimo y obedientísimo, manso y humilde de corazón, amante de la castidad, Amor nuestro, Dios de la paz, Autor de la vida, Modelo de las virtudes, Buen Pastor, Luz verdadera, Sabiduría eterna, Camino y vida nuestra, ten piedad de nosotros.`,
    la: `Kyrie, eleison. Christe, eleison. Kyrie, eleison. Iesu, audi nos. Iesu, exaudi nos.
Iesu, Fili Dei vivi, splendor Patris, Rex gloriae, Sol iustitiae, Fili Mariae Virginis, mitis et humilis corde, amator castitatis, Amor noster, Bone Pastor, Lux vera, Sapientia aeterna, Via et vita nostra, miserere nobis.`
  }
};

// 6. LOS 33 DÍAS + DÍA 34 CON REFERENCIAS EXACTAS AL TRATADO DE LA VERDADERA DEVOCIÓN (TVD)
window.DAYS_DATA = [
  { day: 1, stage: 1, title: "Las Bienaventuranzas frente a las máximas del mundo", source: "San Mateo 5, 1–19 · Tratado de la Verdadera Devoción (TVD), nn. 78–80 y 227", text: `<p>«Bienaventurados los pobres de espíritu, porque de ellos es el Reino de los cielos. Bienaventurados los mansos... Bienaventurados los limpios de corazón, porque ellos verán a Dios.» (Mt 5, 3–8). Enseña San Luis María (TVD, nn. 78–79 y 227) que antes de consagrarse es indispensable emplear doce días en vaciarse del espíritu del mundo, opuesto al de Jesucristo.</p>`, practice: "Aparta hoy de tu corazón toda búsqueda de aplauso mundano y busca solo la mirada de Dios.", jaculatoria: "«Renuncio a Satanás, a sus pompas y a sus obras, y me entrego a Jesucristo por María.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 2, stage: 1, title: "La perfección cristiana y la pureza de intención", source: "San Mateo 5, 48; 6, 1–15 · Imitación de Cristo, Lib. I, cap. 1 · TVD, n. 81", text: `<p>«El que me sigue no anda en tinieblas, dice el Señor. Vanidad de vanidades y todo vanidad, sino amar y servir solamente a Dios.» Como explica el Tratado (TVD, n. 81), para morir a sí mismo no basta dejar el pecado mortal; hay que purificar las intenciones a ejemplo de María.</p>`, practice: "Cumple tus deberes con serenidad y orden, ofreciendo cada obra a la Santísima Virgen.", jaculatoria: "«Vanidad de vanidades y todo vanidad, sino amar y servir solamente a Dios.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 3, stage: 1, title: "No se puede servir a dos señores: Dios y el mundo", source: "San Mateo 6, 24–34 · Imitación, Lib. I, cap. 2 · TVD, n. 126", text: `<p>«Nadie puede servir a dos señores... Buscad primero el Reino de Dios y su justicia, y todas estas cosas se os darán por añadidura.» En el Bautismo renunciamos al mundo para pertenecer solo a Jesucristo (TVD, n. 126).</p>`, practice: "Deposita toda inquietud temporal en las manos maternales de Nuestra Señora.", jaculatoria: "«Buscad primero el Reino de Dios y su justicia por medio de María.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 4, stage: 1, title: "La puerta estrecha y el humilde sentir de sí", source: "San Mateo 7, 13–14 · Imitación, Lib. I, cap. 7 · TVD, n. 139", text: `<p>«Entrad por la puerta estrecha, porque ancha es la puerta y espacioso el camino que lleva a la perdición... No estribes en ti mismo, mas pon toda tu esperanza en Dios y en su Madre Santísima.» (TVD, n. 139).</p>`, practice: "Acepta hoy con dulzura cualquier contrariedad sin quejarte.", jaculatoria: "«¡Señor, que yo vea tu camino estrecho y seguro!»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 5, stage: 1, title: "Las tres falsas sabidurías: terrena, carnal y diabólica", source: "El Amor de la Sabiduría Eterna (ASE), nn. 74–80 · Imitación, Lib. I, cap. 13", text: `<p>Enseña San Luis María (ASE, nn. 74–80) que existen tres falsas sabidurías que engañan al mundo: la terrena (amor a las riquezas), la carnal (búsqueda del placer y pereza) y la diabólica (soberbia intelectual). María es Trono de la Sabiduría verdadera.</p>`, practice: "Ofrece hoy una pequeña mortificación de la vista o del gusto en honor de la Virgen.", jaculatoria: "«Sabiduría eterna y encarnada, destruye en mí la falsa sabiduría del mundo.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 6, stage: 1, title: "El silencio interior donde obra el Espíritu Santo", source: "Imitación de Cristo, Lib. I, caps. 18 y 20 · TVD, n. 259", text: `<p>«En el silencio y quietud aprovecha el ánima devota y aprende los secretos de Dios.» Enseña San Luis María (TVD, n. 259) que el alma de María es el santuario del recogimiento donde el Espíritu Santo forma a los santos.</p>`, practice: "Guarda hoy paz y silencio interior antes de hablar o juzgar.", jaculatoria: "«Habla, Señor, que tu siervo escucha en el corazón de María.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 7, stage: 1, title: "La brevedad de la vida y la memoria de la eternidad", source: "Imitación de Cristo, Lib. I, caps. 22 y 23 · TVD, n. 172", text: `<p>«Así te deberías haber en toda obra y pensamiento como si hoy hubieses de morir.» Para quien todo lo ha entregado a María, la muerte es dulce tránsito hacia Jesucristo (TVD, n. 172).</p>`, practice: "Realiza hoy tu oración con el fervor con que desearías haberla hecho en la hora de tu muerte.", jaculatoria: "«Santa María, Madre de Dios, ruega por nosotros ahora y en la hora de nuestra muerte.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 8, stage: 1, title: "El juicio divino y la enmienda fervorosa de vida", source: "Imitación de Cristo, Lib. I, caps. 24 y 25 · TVD, n. 85", text: `<p>«En todas las cosas mira el fin, y cómo estarás delante de aquel Juez justísimo.» No nos atrevemos a comparecer solos ante Dios sin la mediación de María, nuestra Abogada (TVD, n. 85).</p>`, practice: "Renueva tu propósito de huir de toda ocasión de pecado venial deliberado.", jaculatoria: "«Aplaca, Señora y Abogada nuestra, la justa ira de tu Divino Hijo.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 9, stage: 1, title: "El camino real de la Santa Cruz", source: "Imitación de Cristo, Lib. II, caps. 1 y 12 · TVD, n. 154", text: `<p>«En la Cruz está la salud, en la Cruz está la vida, en la Cruz está la defensa contra los enemigos.» María hace que las cruces más pesadas se vuelvan dulces y meritorias (TVD, n. 154).</p>`, practice: "Besa con amor el Santo Crucifijo y une tus fatigas de hoy a la Cruz de Cristo.", jaculatoria: "«Te adoramos, oh Cristo, y te bendecimos, que por tu Santa Cruz redimiste al mundo.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 10, stage: 1, title: "Custodiar la gracia en el tesoro de la humildad", source: "Imitación de Cristo, Lib. III, caps. 7 y 10 · TVD, n. 88", text: `<p>«Más seguro es esconder la gracia de la devoción bajo el velo de la humildad.» Quien camina solo lleva sus tesoros en vasos frágiles; quien se consagra a María los guarda en el Arca segura de Dios (TVD, n. 88).</p>`, practice: "Agradece a Dios todo bien sin atribuirte mérito propio.", jaculatoria: "«No a nosotros, Señor, sino a tu Nombre y a María da la gloria.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 11, stage: 1, title: "Libertad del corazón frente a las criaturas", source: "Imitación de Cristo, Lib. III, caps. 20 y 31 · TVD, n. 127", text: `<p>«Mientras alguna cosa creada me detiene desordenadamente, no puedo volar libremente a Ti.» La santa esclavitud de amor rompe las cadenas del mundo y dilata el corazón (TVD, n. 127).</p>`, practice: "Corta hoy cualquier distracción inútil para dedicar más tiempo a la oración.", jaculatoria: "«¡Dios mío y Todo mío! Hazme libre del mundo para ser esclavo de tu Amor.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },
  { day: 12, stage: 1, title: "Abnegación de sí mismo y clausura de los Doce Días", source: "Imitación de Cristo, Lib. III, caps. 32 y 40 · TVD, nn. 82 y 227", text: `<p>«Hijo, deja a ti mismo y me hallarás a Mí.» Con este duodécimo día concluye la primera etapa de vaciamiento del espíritu del mundo (TVD, n. 227) para entrar mañana en la Primera Semana del conocimiento propio.</p>`, practice: "Renueva tu deseo de entregar tu voluntad entera en manos de la Santísima Virgen.", jaculatoria: "«Dejo mi espíritu propio para recibir el espíritu purísimo de María.»", prayers: ["veniCreator", "aveMarisStella", "magnificat"] },

  // PRIMERA SEMANA (Días 13 al 19: Conocimiento de sí mismo — TVD, n. 228)
  { day: 13, stage: 2, title: "Conocer nuestro fondo corrompido a la luz del Espíritu Santo", source: "San Lucas 11, 1–10 · Tratado de la Verdadera Devoción (TVD), nn. 78–80 y 228", text: `<p>«Durante la primera semana dedicarán todas sus oraciones y actos de piedad a pedir el conocimiento de sí mismos y la contrición de sus pecados, y lo harán todo con espíritu de humildad, meditando lo que hemos dicho sobre nuestro mal fondo.» (TVD, n. 228).</p>`, practice: "Pide hoy con humildad ver tus faltas sin excusarte.", jaculatoria: "«Domine, ut videam; Noverim me — ¡Señor, que yo vea; que me conozca a mí mismo!»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 14, stage: 2, title: "Cómo el amor propio mancha nuestras obras sin María", source: "San Lucas 13, 1–9 · Tratado de la Verdadera Devoción (TVD), nn. 81–84", text: `<p>Enseña San Luis María (TVD, nn. 81–83) que el pecado original y nuestros pecados actuales han dejado un fermento de orgullo y amor propio que mancha nuestras mejores obras; por ello es necesario depositarlas en las manos virginales de María para que Ella las purifique.</p>`, practice: "Desconfía de tu propia suficiencia y apóyate filialmente en María.", jaculatoria: "«Madre purísima, purifica mis obras de toda mancha de amor propio.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 15, stage: 2, title: "El Hijo Pródigo y la contrición sincera", source: "San Lucas 15, 11–32 · Imitación, Lib. III, cap. 8 · TVD, n. 130", text: `<p>«Me levantaré e iré a mi padre, y le diré: Padre, he pecado contra el cielo y delante de ti.» La consagración repara la infidelidad a los votos de nuestro Santo Bautismo (TVD, n. 130).</p>`, practice: "Pide perdón de corazón por tus infidelidades pasadas a las promesas bautismales.", jaculatoria: "«Padre, he pecado; recíbeme por manos de María, Refugio de los pecadores.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 16, stage: 2, title: "La humildad profunda según San Bernardo", source: "San Lucas 16, 1–13 · Tratado de la Verdadera Devoción (TVD), nn. 85 y 228", text: `<p>Considera hoy con San Bernardo y San Luis María (TVD, nn. 85, 228) nuestra pequeñez radical ante la Majestad infinita de Dios, para comprender cuánta necesidad tenemos de acercarnos a Él por medio de María.</p>`, practice: "Acepta con paz cualquier corrección o humillación del día.", jaculatoria: "«Al corazón contrito y humillado, oh Dios, no lo desprecias.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 17, stage: 2, title: "«Siervos inútiles somos» ante el tesoro de María", source: "San Lucas 17, 1–10 · Imitación, Lib. III, cap. 14 · TVD, nn. 86–89", text: `<p>«Cuando hubiereis hecho todo lo que os está mandado, decid: Siervos inútiles somos.» Para no perder el mérito de nuestras oraciones y ayunos por la vanagloria, los entregamos en custodia a la Reina del Cielo (TVD, nn. 86–89).</p>`, practice: "Entrega a Nuestra Señora cada pequeño deber cumplido hoy sin vanagloria.", jaculatoria: "«Siervo inútil soy, Señor; guarda mis pobres obras en el tesoro de María.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 18, stage: 2, title: "La oración humilde del publicano", source: "San Lucas 18, 9–14 · Imitación, Lib. III, cap. 47 · TVD, n. 143", text: `<p>«El publicano se golpeaba el pecho diciendo: ¡Oh Dios, sé propicio a mí, pecador!» Dios resiste a los soberbios y da su gracia a los humildes por manos de la humilde esclava del Señor (TVD, n. 143).</p>`, practice: "Ora hoy de rodillas con profunda reverencia y humildad.", jaculatoria: "«¡Oh Dios, sé propicio a mí, pecador, por los ruegos de María Inmaculada!»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 19, stage: 2, title: "El clamor del ciego de Jericó y clausura de la Primera Semana", source: "San Lucas 18, 35–43 · Imitación, Lib. III, cap. 55 · TVD, n. 228", text: `<p>«¡Señor, que yo vea! Y Jesús le dijo: Ve; tu fe te ha salvado.» Con este séptimo día concluye la Primera Semana del conocimiento propio (TVD, n. 228) para entrar mañana en la Segunda Semana dedicada al conocimiento de María Santísima.</p>`, practice: "Dispón tu examen de conciencia para confesarte antes del día de tu Consagración.", jaculatoria: "«¡Jesús, Hijo de David, ten compasión de mí! ¡Señor, que yo vea!»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },

  // SEGUNDA SEMANA (Días 20 al 26: Conocimiento de la Santísima Virgen — TVD, n. 229)
  { day: 20, stage: 3, title: "María, paraíso terrenal del nuevo Adán y aurora de salvación", source: "San Lucas 1, 26–38 · Tratado de la Verdadera Devoción (TVD), nn. 1–13 y 229", text: `<p>«Por María comenzó la salvación del mundo, y por María debe consumarse. La divina María es el paraíso terrenal del nuevo Adán, donde Él se encarnó por obra del Espíritu Santo para obrar maravillas incomprensibles.» (TVD, nn. 1, 6, 14 y 229).</p>`, practice: "Durante esta Segunda Semana reza diariamente el Santo Rosario pidiendo al Espíritu Santo conocer a María.", jaculatoria: "«He aquí la esclava del Señor; hágase en mí según tu palabra.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 21, stage: 3, title: "Cómo la Santísima Trinidad obra en María y por María", source: "San Lucas 1, 39–56 · Tratado de la Verdadera Devoción (TVD), nn. 14–36", text: `<p>«Dios Padre reunió todas las aguas y las llamó mar (maria); reunió todas sus gracias y las llamó María (n. 23). Dios Hijo la hizo tesorera de todos sus méritos (n. 24). Dios Espíritu Santo comunicó a María, su fiel Esposa, todos sus dones y la escogió por dispensadora de cuanto posee (n. 25).»</p>`, practice: "Recuerda hoy en cada Avemaría que toda gracia nos llega por las manos maternales de María.", jaculatoria: "«Totum nos habere voluit per Mariam — Dios quiso que todo lo tengamos por María.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 22, stage: 3, title: "La maternidad espiritual de Nuestra Señora y los últimos tiempos", source: "San Lucas 2, 15–38 · Tratado de la Verdadera Devoción (TVD), nn. 37–59", text: `<p>«Si Jesucristo, Cabeza de los hombres, ha nacido en Ella, los predestinados, que son miembros de esta Cabeza, deben también nacer y formarse en Ella por consecuencia necesaria (n. 32)... En los últimos tiempos María formará a los grandes santos que harán triunfar a Jesucristo (nn. 47–59).»</p>`, practice: "Pide a la Santísima Virgen que te eduque y moldee según sus propios modos maternales.", jaculatoria: "«Formad en mí, ¡oh Madre admirable!, la imagen viva de vuestro Hijo Jesucristo.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 23, stage: 3, title: "Las cinco notas de la Verdadera Devoción a la Virgen", source: "San Juan 2, 1–11 (Bodas de Caná) · TVD, nn. 90–110", text: `<p>Frente a las siete falsas devociones (nn. 92–104), la verdadera devoción a Nuestra Señora es: 1) <strong>Interior</strong>, 2) <strong>Tierna</strong>, 3) <strong>Santa</strong>, 4) <strong>Constante</strong> y 5) <strong>Desinteresada</strong> (TVD, nn. 105–110).</p>`, practice: "Esfuérzate hoy por imitar la suavidad, pureza de intención y constancia de María.", jaculatoria: "«Haced todo lo que Él os diga.» (Jn 2, 5).", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 24, stage: 3, title: "Las diez virtudes evangélicas de María Santísima", source: "San Juan 19, 25–27 · Tratado de la Verdadera Devoción (TVD), nn. 108 y 135–151", text: `<p>Contempla las diez virtudes principales de la Santísima Virgen (TVD, n. 108): 1) humildad profunda, 2) fe viva, 3) obediencia ciega, 4) oración continua, 5) mortificación universal, 6) pureza divina, 7) caridad ardiente, 8) paciencia heroica, 9) dulzura angélica y 10) sabiduría divina.</p>`, practice: "Practica hoy especialmente la dulzura angélica, la pureza y la paciencia de María.", jaculatoria: "«Virgo fidelis, hazme imitador de tu fe viva y de tu humildad profunda.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 25, stage: 3, title: "María, camino fácil, corto, perfecto y seguro, y molde de Dios", source: "Hechos 1, 12–14 · Tratado de la Verdadera Devoción (TVD), nn. 152–182 y 219", text: `<p>«Esta devoción es un camino fácil, corto, perfecto y seguro para llegar a la unión con Nuestro Señor (n. 152)... María es el gran molde de Dios (forma Dei) hecho por el Espíritu Santo: quien es arrojado en este molde divino y se deja manejar con docilidad, recibe pronto todos los rasgos de Jesucristo (n. 219).»</p>`, practice: "Abandónate hoy con docilidad total en las manos de María como metal fundido en su molde.", jaculatoria: "«María es el gran molde de Dios: arrójame en Ti, Madre mía, para salir semejante a Jesús.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },
  { day: 26, stage: 3, title: "Figura bíblica de Rebeca y Jacob: oficios maternales de María", source: "Apocalipsis 12, 1–17 · Tratado de la Verdadera Devoción (TVD), nn. 183–212", text: `<p>Así como Rebeca vistió a su hijo menor Jacob con las vestiduras perfumadas del primogénito para alcanzarle la bendición de Isaac, la Santísima Virgen ama, alimenta, guía, defiende y reviste de los méritos de Jesucristo a sus fieles esclavos de amor (TVD, nn. 183–212).</p>`, practice: "Concluye la Segunda Semana agradeciendo a Nuestra Señora todos los oficios maternales que ejerce contigo.", jaculatoria: "«Bajo tu amparo nos acogemos, Santa Madre de Dios.»", prayers: ["letaniasEspiritu", "aveMarisStella", "letaniasLauretanas"] },

  // TERCERA SEMANA (Días 27 al 33: Conocimiento de Jesucristo — TVD, n. 230)
  { day: 27, stage: 4, title: "Jesucristo, nuestro único Fin Último: «A Jesús por María»", source: "Tratado de la Verdadera Devoción (TVD), nn. 60–67 y 230 · Imitación, Lib. II, cap. 7", text: `<p>«Jesucristo nuestro Salvador, verdadero Dios y verdadero Hombre, debe ser el fin último de todas nuestras demás devociones; de lo contrario, serían falsas y engañosas. Establecemos la sólida devoción a la Santísima Virgen sólo para establecer más perfectamente la de Jesucristo.» (TVD, nn. 61–62, 230).</p>`, practice: "Repite cien veces hoy con San Agustín: «Noverim Te, Domine — ¡Señor Jesucristo, que yo te conozca!»", jaculatoria: "«¡Señor Jesucristo, que yo te conozca para amarte con el corazón de María!»", prayers: ["letaniasEspiritu", "aveMarisStella", "oracionSanAgustin", "letaniasJesus"] },
  { day: 28, stage: 4, title: "Jesús sometido a María durante treinta años en Nazaret", source: "San Lucas 2, 51–52 · TVD, nn. 18 y 139 · Amor de la Sabiduría Eterna (ASE), nn. 104–132", text: `<p>«Jesucristo dio más gloria a Dios su Padre con la sumisión que tuvo a su Madre durante treinta años en Nazaret, que la que le hubiera dado convirtiendo toda la tierra con los mayores milagros. ¡Cuán altamente glorificamos a Dios cuando nos sometemos a María a ejemplo de Jesucristo!» (TVD, n. 18).</p>`, practice: "Honra hoy la vida oculta de Nazaret trabajando con paz, orden y obediencia.", jaculatoria: "«Et erat subditus illis — Y Jesús les estaba sujeto en Nazaret.»", prayers: ["letaniasEspiritu", "aveMarisStella", "oracionSanAgustin", "letaniasJesus"] },
  { day: 29, stage: 4, title: "La mansedumbre y caridad infinita del Corazón de Jesús", source: "El Amor de la Sabiduría Eterna (ASE), nn. 154–166 · Imitación, Lib. II, cap. 8", text: `<p>«Su rostro es tan dulce y apacible, que encantaba los ojos y los corazones de cuantos le veían. Aprended de Mí, que soy manso y humilde de corazón, y hallaréis descanso para vuestras almas.» (ASE, n. 156).</p>`, practice: "Haz hoy una visita espiritual o presencial a Jesús Sacramentado en unión con María.", jaculatoria: "«Jesús, manso y humilde de corazón, haz mi corazón semejante al tuyo por medio de María.»", prayers: ["letaniasEspiritu", "aveMarisStella", "oracionSanAgustin", "letaniasJesus"] },
  { day: 30, stage: 4, title: "El triunfo de la Sabiduría Encarnada en la Santa Cruz", source: "San Mateo 27, 27–50 · El Amor de la Sabiduría Eterna (ASE), nn. 167–180 · TVD, n. 154", text: `<p>«Jamás encontró la Sabiduría Eterna tanto reposo ni tanta gloria como sobre el árbol de la Cruz; por eso hizo de la Cruz su trono real y su altar. La Sabiduría es la Cruz, y la Cruz es la Sabiduría.» (ASE, nn. 167, 180).</p>`, practice: "Ofrece hoy con amor y sin murmurar las pequeñas fatigas de tu jornada.", jaculatoria: "«Jamás me gloriaré sino en la Cruz de Nuestro Señor Jesucristo.»", prayers: ["letaniasEspiritu", "aveMarisStella", "oracionSanAgustin", "letaniasJesus"] },
  { day: 31, stage: 4, title: "La Consagración Total como perfecta renovación de los votos bautismales", source: "Tratado de la Verdadera Devoción (TVD), nn. 120–134", text: `<p>«Esta devoción consiste en entregarse enteramente a la Santísima Virgen para pertenecer enteramente a Jesucristo por medio de Ella. Es menester entregarle: 1.º nuestro cuerpo con todos sus sentidos; 2.º nuestra alma con todas sus potencias; 3.º nuestros bienes exteriores; y 4.º nuestros bienes interiores y espirituales, esto es, nuestros méritos, virtudes y el valor satisfactorio e impetratorio de todas nuestras buenas obras pasadas, presentes y futuras, sin reserva alguna.» (TVD, n. 121).</p>`, practice: "Medita pausadamente la Fórmula de Consagración que firmarás al término de esta semana.", jaculatoria: "«Renuevo y ratifico hoy en manos de María los votos de mi Santo Bautismo.»", prayers: ["letaniasEspiritu", "aveMarisStella", "oracionSanAgustin", "letaniasJesus"] },
  { day: 32, stage: 4, title: "Los siete efectos maravillosos de la Santa Esclavitud de Amor", source: "Tratado de la Verdadera Devoción (TVD), nn. 213–225", text: `<p>Enseña San Luis María (TVD, nn. 213–225) los siete frutos de esta consagración en quien la vive fielmente: 1) conocimiento de nuestra bajeza; 2) participación en la fe pura de María; 3) don del puro amor sin temor servil; 4) gran confianza en Dios y en María; 5) comunicación del alma y del espíritu de María; 6) transformación en Cristo; y 7) mayor gloria de la Santísima Trinidad.</p>`, practice: "Acércate a la Confesión sacramental para preparar tu alma al día de tu Consagración.", jaculatoria: "«Que el alma de María esté en mí para engrandecer al Señor; que su espíritu esté en mí para regocijarse en Dios.»", prayers: ["letaniasEspiritu", "aveMarisStella", "oracionSanAgustin", "letaniasJesus"] },
  { day: 33, stage: 4, title: "Víspera de la Consagración: Obrar por María, con María, en María y para María", source: "Tratado de la Verdadera Devoción (TVD), nn. 257–273", text: `<p>«Es menester hacer todas nuestras acciones habitualmente <strong>por María</strong> (obedeciéndola en todo), <strong>con María</strong> (imitándola como modelo acabado), <strong>en María</strong> (recogidos en su interior) y <strong>para María</strong> (trabajando por su honra), a fin de hacerlas más perfectamente por Jesucristo, con Jesucristo, en Jesucristo y para Jesucristo.» (TVD, nn. 257–265).</p>`, practice: "Firma e imprime hoy tu Pergamino de Consagración para tenerlo listo mañana tras la Sagrada Comunión.", jaculatoria: "«Todo por María, con María, en María y para María, para vivir en Jesús.»", prayers: ["letaniasEspiritu", "aveMarisStella", "oracionSanAgustin", "letaniasJesus"] },
  { day: 34, stage: 5, title: "✠ Día Solemne de la Consagración Total a Jesús por María", source: "Tratado de la Verdadera Devoción (TVD), nn. 231–233 y 266–273", text: `<p><strong>Rúbrica solemne de San Luis María Grignion de Montfort (TVD, nn. 231–232):</strong></p><p>«Al fin de las tres semanas se confesará y comulgará con la intención de entregarse a Jesucristo en calidad de esclavo de amor, por medio de María; y después de la Comunión —recibida según el método montfortiano (TVD, nn. 266–273)— recitará la Fórmula de Consagración, que convendrá escribir o hacer escribir, si no está impresa, y <strong>firmar el mismo día que la haga</strong>. Bueno será que en ese día pague algún tributo a Jesucristo y a la Santísima Virgen.»</p>`, practice: "Pulsa el botón dorado de abajo para adjuntar tu firma manuscrita digital e imprimir tu Acta Solemne de Consagración en formato A4.", jaculatoria: "«¡Soy todo tuyo y todo lo mío te pertenece, oh mi amable Jesús, por María, tu Santísima Madre!»", prayers: ["aveMarisStella", "magnificat"] }
];
